import {readFile,writeFile} from 'node:fs/promises';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);const {parse}=require('acorn');
const file=process.argv[2];let source=await readFile(file,'utf8');if(source.includes('await window.SICIPCentralBoot;'))throw Error('La base ya está parcheada; usa el despliegue original documentado.');const ast=parse(source,{ecmaVersion:'latest',sourceType:'module'}),nodes=new Map(ast.body.filter(n=>n.type==='FunctionDeclaration').map(n=>[n.id.name,n]));const edits=[];
for(const [name,method] of [['_C','sdkCount'],['Jr','sdkGetDocs'],['Za','sdkGetDoc'],['tu','sdkWrite'],['es','sdkWrite'],['cm','sdkWrite']]){const n=nodes.get(name);if(!n)throw Error('No se identifica la función SDK '+name);edits.push({start:n.id.start,end:n.id.end,text:'__sicipOriginal_'+name});source+='\nfunction '+name+'(...args){return window.SICIPCentral.'+(name==='cm'?'sdkCreate':method)+'('+(name==='cm'?'args':'args[0]')+',()=>__sicipOriginal_'+name+'(...args));}\n';}
for(const [name,code] of [['NC','async function NC(t,e){const u=await window.SICIPCentral.login(t,e);CC(u);return u;}'],['RC','function RC(){sessionStorage.removeItem("sicip_usuario");sessionStorage.removeItem("sicip_matricula");window.SICIPCentral.logout().catch(()=>{});}'],['PC','async function PC(t,e){if(String(t)!==String(window.SICIPCentral.user?.matricula))throw Error("No puedes cambiar la contraseña de otra cuenta.");return window.SICIPCentral.changePassword(e);}']]){const n=nodes.get(name);if(!n)throw Error('No se identifica '+name);edits.push({start:n.start,end:n.end,text:code});}
for(const e of edits.sort((a,b)=>b.start-a.start))source=source.slice(0,e.start)+e.text+source.slice(e.end);
source='await window.SICIPCentralBoot;\n'+source;await writeFile(file,source);parse(source,{ecmaVersion:'latest',sourceType:'module'});console.log('Bundle conectado: autenticación de sesión y lecturas de dominio; trámites preservados.');
